<script setup lang="ts">
import { reactive, ref, watch } from "vue";
import { KeyRound, Plus, X } from "lucide-vue-next";
import { api, apiError } from "../services/api";
import { useAuthStore } from "../stores/auth";
const auth=useAuthStore(), tab=ref("business"), loading=ref(false), saving=ref(false), error=ref(""), success=ref(""), users=ref<any[]>([]), showUser=ref(false);
const business=reactive({name:"",legalName:"",taxId:"",taxCondition:"",address:"",phone:"",logoUrl:""}); const afip=reactive({issuerTaxId:"",certificateContent:"",privateKeyContent:"",certificatePassphrase:"",certificateAlias:"",isPfxCertificate:false,environment:1,salesPoint:1,defaultConcept:1}); const user=reactive({firstName:"",lastName:"",email:"",password:"",role:"Seller"});
async function load(){if(!auth.tenantId)return;loading.value=true;try{const [b,u]=await Promise.all([api.get("/settings/business",{params:{tenantId:auth.tenantId}}),api.get("/users",{params:{tenantId:auth.tenantId}})]);Object.assign(business,b.data);users.value=u.data;}catch(e){error.value=apiError(e)}finally{loading.value=false}}
async function saveBusiness(){saving.value=true;try{await api.put("/settings/business",{tenantId:auth.tenantId,...business});success.value="Datos actualizados."}catch(e){error.value=apiError(e)}finally{saving.value=false}}
async function saveAfip(){saving.value=true;try{await api.post("/settings/afip-cert",{tenantId:auth.tenantId,...afip});success.value="Certificado AFIP guardado."}catch(e){error.value=apiError(e)}finally{saving.value=false}}
async function saveUser(){saving.value=true;try{await api.post("/users",{tenantId:auth.tenantId,...user});showUser.value=false;await load()}catch(e){error.value=apiError(e)}finally{saving.value=false}}
async function toggle(u:any){try{await api.put(`/users/${u.id}/toggle-status`,{tenantId:auth.tenantId,isActive:!u.isActive});await load()}catch(e){error.value=apiError(e)}} watch(()=>auth.tenantId,load,{immediate:true});
</script>
<template><div class="page-heading"><div><div class="breadcrumb">Tu negocio / Configuración</div><h1>Configuración</h1><p>Datos comerciales, AFIP y permisos del equipo.</p></div></div><p v-if="error" class="error">{{error}}</p><p v-if="success" class="success">{{success}}</p><div class="tabs"><button :class="{active:tab==='business'}" @click="tab='business'">Empresa</button><button :class="{active:tab==='afip'}" @click="tab='afip'">AFIP</button><button :class="{active:tab==='users'}" @click="tab='users'">Usuarios</button></div><section v-if="tab==='business'" class="panel"><h2>Datos de la empresa</h2><form @submit.prevent="saveBusiness" class="form-grid"><label>Nombre comercial<input v-model="business.name" required/></label><label>Razón social<input v-model="business.legalName"/></label><label>CUIT<input v-model="business.taxId" inputmode="numeric" required/></label><label>Condición IVA<input v-model="business.taxCondition" placeholder="Responsable Inscripto"/></label><label class="wide">Dirección<input v-model="business.address"/></label><label>Teléfono<input v-model="business.phone"/></label><label>Logo URL<input v-model="business.logoUrl" type="url"/></label><button class="primary full" :disabled="saving">Guardar cambios</button></form></section><section v-if="tab==='afip'" class="panel"><h2>Facturación AFIP</h2><form @submit.prevent="saveAfip" class="form-grid"><label>CUIT emisor<input v-model="afip.issuerTaxId" required/></label><label>Punto de venta<input v-model.number="afip.salesPoint" type="number" min="1"/></label><label>Alias certificado<input v-model="afip.certificateAlias" required/></label><label>Entorno<select v-model.number="afip.environment"><option :value="1">Homologación</option><option :value="2">Producción</option></select></label><label class="wide">Certificado .crt<textarea v-model="afip.certificateContent" required/></label><label class="wide">Clave privada .key<textarea v-model="afip.privateKeyContent" required/></label><button class="primary full" :disabled="saving"><KeyRound :size="16"/>Guardar certificado</button></form></section><section v-if="tab==='users'" class="panel"><div class="section-heading"><h2>Usuarios y permisos</h2><button class="primary" @click="showUser=true"><Plus :size="16"/>Nuevo usuario</button></div><div class="responsive-table"><table><thead><tr><th>Usuario</th><th>Rol</th><th>Estado</th><th></th></tr></thead><tbody><tr v-for="u in users" :key="u.id"><td>{{u.firstName}} {{u.lastName}}<small>{{u.email}}</small></td><td><span class="badge">{{u.role}}</span></td><td><span :class="u.isActive?'status success-status':'status danger'">{{u.isActive?'Activo':'Inactivo'}}</span></td><td><button class="secondary" @click="toggle(u)">{{u.isActive?'Desactivar':'Activar'}}</button></td></tr></tbody></table></div></section><div v-if="showUser" class="modal-backdrop"><section class="modal"><button class="icon-button modal-close" @click="showUser=false"><X/></button><h2>Nuevo usuario</h2><form @submit.prevent="saveUser"><label>Nombre<input v-model="user.firstName" required/></label><label>Apellido<input v-model="user.lastName" required/></label><label>Email<input v-model="user.email" type="email" required/></label><label>Clave<input v-model="user.password" type="password" minlength="12" required/></label><label>Rol<select v-model="user.role"><option value="Admin">Admin</option><option value="Seller">Cajero</option><option value="Warehouse">Stock Manager</option></select></label><button class="primary full">Crear usuario</button></form></section></div></template>
<style scoped>.tabs{display:flex;gap:.5rem;margin-bottom:1rem}.tabs button{padding:.6rem 1rem;border:1px solid #e2e8f0;border-radius:.6rem;background:white}.tabs button.active{color:white;background:#ec4899;border-color:#ec4899}form{display:grid;gap:.8rem}.wide{grid-column:span 2}@media(max-width:600px){.wide{grid-column:span 1}}</style>
